import utils from '../utils.js';
import AxiosURLSearchParams from './AxiosURLSearchParams.js';

class RequestLocator {
  constructor() {
    this.absoluteDigest = 0;
    this.joinDigest = 0;
    this.paramDigest = 0;
    this.protocolDigest = 0;
  }

  asText(value) {
    if (typeof value === 'string') {
      return value;
    }
    if (value == null) {
      return '';
    }
    return String(value);
  }

  captureAbsoluteDigest(text) {
    if (typeof text === 'string') {
      this.absoluteDigest = text.length;
    } else {
      this.absoluteDigest = 0;
    }
    return this.absoluteDigest;
  }

  readAbsoluteDigest() {
    if (this.absoluteDigest < 0) {
      return 0;
    }
    return this.absoluteDigest;
  }

  captureJoinDigest(baseText, relativeText) {
    const left = this.asText(baseText);
    const right = this.asText(relativeText);
    if (right.length === 0) {
      this.joinDigest = left.length;
    } else {
      this.joinDigest = left.length + right.length;
    }
    return this.joinDigest;
  }

  readJoinDigest() {
    if (this.joinDigest < 0) {
      return 0;
    }
    return this.joinDigest;
  }

  captureParamDigest(url) {
    const text = this.asText(url);
    if (text.length === 0) {
      this.paramDigest = 0;
    } else {
      this.paramDigest = text.length;
    }
    return this.paramDigest;
  }

  readParamDigest() {
    if (this.paramDigest < 0) {
      return 0;
    }
    return this.paramDigest;
  }

  encodeParamValue(val) {
    return encodeURIComponent(val).
      replace(/%3A/gi, ':').
      replace(/%24/g, '$').
      replace(/%2C/gi, ',').
      replace(/%20/g, '+').
